CREATE TABLE IF NOT EXISTS products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,name text NOT NULL,sku text,description text,unit_price numeric(14,2) NOT NULL DEFAULT 0,currency char(3) NOT NULL DEFAULT 'INR',tax_rate numeric(6,2) NOT NULL DEFAULT 0,is_active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS quotes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,quote_number text NOT NULL,account_id uuid REFERENCES accounts(id) ON DELETE SET NULL,contact_id uuid REFERENCES contacts(id) ON DELETE SET NULL,status text NOT NULL DEFAULT 'draft',currency char(3) NOT NULL DEFAULT 'INR',subtotal numeric(14,2) NOT NULL DEFAULT 0,tax_total numeric(14,2) NOT NULL DEFAULT 0,total numeric(14,2) NOT NULL DEFAULT 0,valid_until date,created_by uuid REFERENCES users(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,quote_number));
CREATE TABLE IF NOT EXISTS quote_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),quote_id uuid NOT NULL REFERENCES quotes(id) ON DELETE CASCADE,product_id uuid REFERENCES products(id) ON DELETE SET NULL,description text NOT NULL,quantity numeric(12,2) NOT NULL DEFAULT 1,unit_price numeric(14,2) NOT NULL DEFAULT 0,tax_rate numeric(6,2) NOT NULL DEFAULT 0,total numeric(14,2) NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,order_number text NOT NULL,quote_id uuid REFERENCES quotes(id) ON DELETE SET NULL,account_id uuid REFERENCES accounts(id) ON DELETE SET NULL,contact_id uuid REFERENCES contacts(id) ON DELETE SET NULL,status text NOT NULL DEFAULT 'pending',currency char(3) NOT NULL DEFAULT 'INR',subtotal numeric(14,2) NOT NULL DEFAULT 0,tax_total numeric(14,2) NOT NULL DEFAULT 0,total numeric(14,2) NOT NULL DEFAULT 0,created_by uuid REFERENCES users(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,order_number));
CREATE TABLE IF NOT EXISTS order_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES orders(id) ON DELETE CASCADE,product_id uuid REFERENCES products(id) ON DELETE SET NULL,description text NOT NULL,quantity numeric(12,2) NOT NULL DEFAULT 1,unit_price numeric(14,2) NOT NULL DEFAULT 0,tax_rate numeric(6,2) NOT NULL DEFAULT 0,total numeric(14,2) NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS invoices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,invoice_number text NOT NULL,order_id uuid REFERENCES orders(id) ON DELETE SET NULL,account_id uuid REFERENCES accounts(id) ON DELETE SET NULL,status text NOT NULL DEFAULT 'draft',currency char(3) NOT NULL DEFAULT 'INR',subtotal numeric(14,2) NOT NULL DEFAULT 0,tax_total numeric(14,2) NOT NULL DEFAULT 0,total numeric(14,2) NOT NULL DEFAULT 0,due_date date,paid_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,invoice_number));
CREATE TABLE IF NOT EXISTS payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,invoice_id uuid REFERENCES invoices(id) ON DELETE SET NULL,amount numeric(14,2) NOT NULL DEFAULT 0,currency char(3) NOT NULL DEFAULT 'INR',method text,status text NOT NULL DEFAULT 'pending',provider text,provider_reference text,paid_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS plans(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL UNIQUE,name text NOT NULL,description text,monthly_price numeric(14,2) NOT NULL DEFAULT 0,currency char(3) NOT NULL DEFAULT 'INR',limits jsonb NOT NULL DEFAULT '{}',features jsonb NOT NULL DEFAULT '[]',active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS workspace_subscriptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL UNIQUE REFERENCES workspaces(id) ON DELETE CASCADE,plan_id uuid NOT NULL REFERENCES plans(id),status text NOT NULL DEFAULT 'trialing',provider text,provider_subscription_id text,current_period_start timestamptz,current_period_end timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS integrations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,type text NOT NULL,name text NOT NULL,status text NOT NULL DEFAULT 'disabled',config jsonb NOT NULL DEFAULT '{}',secrets_ref text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS products_workspace_idx ON products(workspace_id);
CREATE INDEX IF NOT EXISTS quotes_workspace_idx ON quotes(workspace_id);
CREATE INDEX IF NOT EXISTS orders_workspace_idx ON orders(workspace_id);
CREATE INDEX IF NOT EXISTS invoices_workspace_idx ON invoices(workspace_id);
CREATE INDEX IF NOT EXISTS payments_workspace_idx ON payments(workspace_id);
CREATE INDEX IF NOT EXISTS integrations_workspace_idx ON integrations(workspace_id);
INSERT INTO plans(code,name,description,monthly_price,limits,features) SELECT 'community','Community','Self-hosted community plan',0,'{"users":5,"leads":10000,"integrations":3}','["crm","inbox","automation"]' WHERE NOT EXISTS(SELECT 1 FROM plans WHERE code='community');